def PRAYER_BLOCK(intro_para, short=False):
    NUM(intro_para + " सदर याचिका दि. 13.12.2012 रोजी तयार करण्यात आली असून, त्यातील प्रार्थना (A) ते (F) मूळ याचिकेत आहेत व प्रार्थना (G) ते (P) मा. उच्च न्यायालयाच्या परवानगीने नंतर जोडण्यात आल्या आहेत (" + CP + ", पृ.71-79). याचिकेतील प्रार्थना पुढीलप्रमाणे आहेत:-")
    for k, t in PRAYERS:
        SUB(k, "“" + t + "”")
    if short:
        NUM("परिच्छेद 7 मध्ये नमूद केल्यानुसार मा. उच्च न्यायालयाने दि. 12.06.2026 रोजीच्या आदेशान्वये वरीलपैकी प्रार्थना (B) मंजूर केली आहे.")
        return
    NUM("मा. उच्च न्यायालयाने दि. 12.06.2026 रोजीच्या आदेशान्वये वरीलपैकी प्रार्थना (B) मंजूर केली आहे. सदर आदेशाच्या परिच्छेद 2 मध्ये असे नमूद आहे की, “This petition is moved for limited relief of making the recommendations of Shetty Commission applicable from 01.04.2003 to the Stenographers working in the District Courts and subordinate in view of the order passed by the Hon'ble Apex Court in Interim Application Nos. 71-A, 135-136, 137-138 & 142 in W. P. (C) No. 1022/1989.”")
def ORDERS_2019():
    NUM("सदर याचिकेत मा. उच्च न्यायालयाने सन 2019 मध्ये पुढील आदेश पारित केले आहेत:-")
    SUB(1, "दि. 27.02.2019 रोजीच्या आदेशात (" + CP + ", पृ.80-82) असे नमूद आहे की, “at least as interim measure, this Court is hereby directing the respondent No. 2 to see that Government Resolution dated 15.09.2018 is implemented in all the districts of this State, wherever there is four tier system of stenographer cadre is in existence. The implementation is to be done for the time being w.e.f. 15.09.2018 and the benefits are to be given accordingly at present. This is to be done within 45 days from today.”")
    SUB(2, "दि. 01.03.2019 रोजीच्या आदेशाच्या परिच्छेद 6 मध्ये (" + CP + ", पृ.83-89) असे नमूद आहे की, “this Court is hereby directing the State Government to take step and see that within one month, the posts of typists are created and one typist is provided to every Judicial Officer of subordinate judiciary who can type English and Marathi versions.”")
    SUB(3, "दि. 01.03.2019 रोजीच्या आदेशाच्या पुनर्विलोकनासाठी शासनाने 35 दिवसांच्या विलंब माफीचा दिवाणी अर्ज क्र. 6790/2019 दाखल केला होता. सदर अर्जावरील दि. 10.07.2019 रोजीच्या आदेशात (" + CP + ", पृ.107-108) असे नमूद आहे की, “So, no case is made out for condonation of delay. Therefore, application for condonation of delay caused in filing the application for review and Review Application deserve to be rejected.”")
    SUB(4, "त्यानंतर श्री. मनोज शंकरराव नांगरे व इतर यांनी दि. 27.02.2019 व दि. 01.03.2019 रोजीच्या आदेशांच्या अनुपालनासाठी अवमान याचिका क्र. 819/2019 दाखल केली आहे. सदर अवमान याचिकेतील प्रार्थना (A) मध्ये असे नमूद आहे की, “To punish respondents for intentional disobedience and willful non-compliance of the orders dated 27.02.2019 and 01.03.2019 passed by this Hon'ble Court in Writ Petition No.7187 of 2015;” (" + CP + ", पृ.15)")

